package me.rezapour.f1appserver.apiimport org.springframework.stereotype.Componentimport org.springframework.web.client.RestClient@Componentclass F1ApiClient(    private val restClientBuilder: RestClient.Builder) {    private val client = restClientBuilder        .baseUrl("https://api.jolpi.ca")        .build()    fun getDrivers(): String? {        return client.get()            .uri("/ergast/f1/drivers/")            .retrieve()            .body(String::class.java)    }}